// Wind-Vector Threat Calculator
// Compares each GBIF pest occurrence against the 48h wind history
// and flags occurrences the wind is actively carrying toward the farm.

const cfg = $('Set Search Parameters').first().json;
const farmLat = parseFloat(cfg.farm_latitude);
const farmLon = parseFloat(cfg.farm_longitude);
const toleranceDeg = parseFloat(cfg.alignment_tolerance_deg);

const occurrences = $input.first().json.results || [];

// --- wind history comes from the previous node (Open-Meteo) ---
const wind = $('Fetch Wind Data').first().json.hourly;
const speeds = wind.wind_speed_10m || [];
const dirs = wind.wind_direction_10m || [];

// Circular mean of wind direction over the lookback window
let sinSum = 0, cosSum = 0;
for (const d of dirs) {
  const rad = (d * Math.PI) / 180;
  sinSum += Math.sin(rad);
  cosSum += Math.cos(rad);
}
let avgWindFrom = (Math.atan2(sinSum, cosSum) * 180) / Math.PI;
if (avgWindFrom < 0) avgWindFrom += 360;
const avgWindSpeed = speeds.reduce((a, b) => a + b, 0) / (speeds.length || 1);

// Direction the wind is actually blowing TOWARD (opposite of "from")
const windBlowingToward = (avgWindFrom + 180) % 360;

function toRad(d) { return (d * Math.PI) / 180; }
function toDeg(r) { return (r * 180) / Math.PI; }

// Great-circle bearing from point A to point B (degrees, 0-360)
function bearing(lat1, lon1, lat2, lon2) {
  const y = Math.sin(toRad(lon2 - lon1)) * Math.cos(toRad(lat2));
  const x =
    Math.cos(toRad(lat1)) * Math.sin(toRad(lat2)) -
    Math.sin(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.cos(toRad(lon2 - lon1));
  let brng = toDeg(Math.atan2(y, x));
  return (brng + 360) % 360;
}

// Haversine distance in km
function distanceKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function angularDiff(a, b) {
  const diff = Math.abs(a - b) % 360;
  return diff > 180 ? 360 - diff : diff;
}

function compass(deg) {
  const points = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  return points[Math.round(deg / 45) % 8];
}

const threats = [];
for (const occ of occurrences) {
  const lat = occ.decimalLatitude;
  const lon = occ.decimalLongitude;
  if (lat === undefined || lon === undefined) continue;

  const distance = distanceKm(farmLat, farmLon, lat, lon);
  const bearingToFarm = bearing(lat, lon, farmLat, farmLon);
  const diff = angularDiff(bearingToFarm, windBlowingToward);
  const windAligned = diff <= toleranceDeg;

  threats.push({
    species: occ.species || occ.scientificName || 'Unknown species',
    establishmentMeans: occ.establishmentMeans || 'UNKNOWN',
    locality: occ.locality || occ.stateProvince || occ.country || 'Unknown locality',
    eventDate: occ.eventDate || occ.year || 'Unknown date',
    distance_km: Math.round(distance * 10) / 10,
    bearing_to_farm_deg: Math.round(bearingToFarm),
    wind_alignment_diff_deg: Math.round(diff),
    wind_aligned: windAligned,
    upwind_edge_to_inspect: compass(avgWindFrom),
  });
}

const alignedThreats = threats
  .filter((t) => t.wind_aligned)
  .sort((a, b) => a.distance_km - b.distance_km);

return [
  {
    json: {
      farm_latitude: farmLat,
      farm_longitude: farmLon,
      avg_wind_from_deg: Math.round(avgWindFrom),
      avg_wind_toward_deg: Math.round(windBlowingToward),
      avg_wind_speed_kmh: Math.round(avgWindSpeed * 10) / 10,
      total_occurrences_checked: occurrences.length,
      aligned_threat_count: alignedThreats.length,
      aligned_threats: alignedThreats,
      all_threats: threats,
    },
  },
];
